"""
    Converts the_geom to a dictionary containing SRID and a list of coordinate points
    :param geometry: the_geom in string format
    :return: A ditionary containing srid as a string and coordinates as a 2D list with float values
    """
def geometry_to_list(geometry: Any) -> object {
    coordinates_list = [];
    points = geometry.split(";");
    (srid, coordinates) = (points[0], points[1]);
    srid = srid[5:];
    points = coordinates[11:(len(coordinates) - 1)].split(",");
    for pair in points {
        coord_pair = [];
        for number in pair.split(" ") {
            coord_pair.append(float(number));
        }
        coordinates_list.append(coord_pair);
    }
    return {"srid": int(srid), "coordinates": coordinates_list};
}

"""
    It contains a pair of any two letters that appears at least twice in the string without overlapping,
    like xyxy (xy) or aabcdefgaa (aa), but not like aaa (aa, but it overlaps).
    """
def contains_repeated_pairs(string: Any) -> object {
    import re;
    return bool(re.search(r"(..).*\1", string));
}

"""Takes rows and length of headers to get columns based on 2D list index from rows"""
def get_columns(rows: Any, headers: Any) -> object {
    if headers {
        columns = [[x[j] for x in rows] for j in range(len(headers))];
        return columns;
    } else {
        raise Exception("Could not parse columns because of irregular headers");
    }
}

